#include <windows.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <msvcrt.h> // Para _debugflag e _DEBUG

// Função auxiliar para verificar flags de depuração
bool isDebugMode() {
    return (_debugflag || _DEBUG);
}

// Função auxiliar para verificar se estamos sendo debugados pelo Windows Debugger
bool isBeingDebugged() {
    if (!isDebugMode()) return false;

    DWORD processId = GetCurrentProcessId();
    HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processId);

    if (hProcess == NULL) return false;

    // Verifica se o processo tem um debugger associado
    BOOL hasDebugger = IsProcessInDebugMode(hProcess);
    CloseHandle(hProcess);

    return hasDebugger;
}

// Função auxiliar para tentar injetar um trap (requer Admin)
bool injectTrap() {
    HMODULE hKernel32 = GetModuleHandleA("kernel32.dll");
    if (!hKernel32) return false;

    FARPROC address = GetProcAddress(hKernel32, "NtSetSystemInformation");
    if (!address) return false;

    DWORD_PTR oldValue = 0;
    if (!SetThreadContext(GetCurrentThread(), CONTEXT_CONTROL, address)) {
        return false;
    }

    // Injeta uma instrução RETI (retorna control flow para dentro do kernel, causando falha)
    BYTE instruction[] = { 0xC9 }; // x86 RETI

    if (!WriteProcessMemory(GetCurrentProcess(), address, instruction, sizeof(instruction), &oldValue)) {
        return false;
    }

    return true;
}

